import {defaultSpecification,validateSpecification,fixtureRun,markdownReport,compatibility,canonical} from './specification.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={R:'Reasoning transparency',H:'Helpfulness',C:'Consistency',A:'Context alignment'};
export function saveFile(name,text,type='application/octet-stream'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
export function evidenceLinks(run,turn){
 const spec=run.specification;const issues=(run.issues||[]).filter(i=>i.checkpoints?.some(p=>p.turn===turn));
 if(!spec)return '<details class="evidence-chain"><summary>Earlier context &amp; assessment scope</summary><p>Imported scores have not been linked into a verified issue trajectory.</p><button class="text-link" data-turn="1">Read the initial user requirements ↗</button></details>';
 return '<section class="evidence-chain"><span class="eyebrow">CROSS-TURN EVIDENCE</span>'+issues.map(i=>'<h3>'+esc(i.title)+'</h3><div class="chain-links"><button data-turn="1">Initial request · T1</button><button data-turn="'+i.first_observed+'">First observed · T'+i.first_observed+'</button>'+i.failing_turns.filter(n=>n!==i.first_observed).map(n=>'<button data-turn="'+n+'">Failing check · T'+n+'</button>').join('')+i.correction_turns.map(n=>'<button data-turn="'+n+'">Correction check · T'+n+'</button>').join('')+'</div><p>'+esc(i.recovery)+'</p>').join('')+(!issues.length?'<p>No issue linked to this checkpoint. Only the configured checks are covered.</p>':'')+'</section>';
}
export function createStudio(api){
 let spec;try{spec=JSON.parse(localStorage.getItem('deeproject-v4-spec'))}catch{}if(!spec||!spec.context||!Array.isArray(spec.criteria)||!spec.criteria.length)spec=defaultSpecification();
 let saved;try{saved=localStorage.getItem('deeproject-v4-committed')}catch{}saved=saved||canonical(defaultSpecification());
 let step=0,criterionIndex=0,errors=[],filter='aircraft',busy=false;
 const main=()=>document.querySelector('#main'),c=()=>spec.criteria[criterionIndex],persist=()=>{try{localStorage.setItem('deeproject-v4-spec',JSON.stringify(spec))}catch{api.toast('Storage unavailable; download your specification.')}};
 const tabs=active=>'<nav class="studio-tabs" aria-label="Workbench stages">'+[['design','01','Design'],['run','02','Run'],['workbench','03','Results']].map(([p,n,t])=>'<a href="#'+p+'" '+(active===p?'aria-current="page" class="active"':'')+'><span>'+n+'</span>'+t+'</a>').join('')+'</nav>';
 const field=(label,name,value,area=false,hint='')=>'<label class="design-field"><span>'+label+'</span>'+(area?'<textarea name="'+name+'" rows="3" required>'+esc(value)+'</textarea>':'<input name="'+name+'" value="'+esc(value)+'" required maxlength="300">')+(hint?'<small>'+hint+'</small>':'')+'</label>';
 function capture(){const before=canonical(spec);const form=document.querySelector('#design-form');if(!form)return;const f=new FormData(form);for(const k of ['domain','task','source','stakeholders'])if(f.has(k))spec.context[k]=String(f.get(k)).trim();for(const k of ['definition','evidence','dimension'])if(f.has(k))c()[k]=String(f.get(k)).trim();for(const n of ['1','2','3'])if(f.has('anchor'+n))c().anchors[n]=String(f.get('anchor'+n)).trim();if(f.has('from_turn'))c().applicability={from_turn:Number(f.get('from_turn')),to_turn:f.get('to_turn')?Number(f.get('to_turn')):null};if(f.has('evaluator')){const type=f.get('evaluator');c().evaluator=type==='required_phrase'?{type,phrase:String(f.get('phrase')||'').trim(),case_sensitive:f.has('case_sensitive')}:type==='python'?{type,callable:String(f.get('callable')||'').trim(),version:String(f.get('evaluator_version')||'v1')}:{type:'unbound'};}if(f.has('review_note'))spec.review={status:f.has('reviewed')?'reviewed':'draft',note:String(f.get('review_note')).trim()};if(canonical(spec)!==before&&!f.has('review_note'))spec.review.status='draft';persist();}
 function commit(){capture();errors=validateSpecification(spec);if(errors.length){design();return false;}if(canonical(spec)!==saved){spec.version++;saved=canonical(spec);}try{localStorage.setItem('deeproject-v4-committed',saved)}catch{}persist();return true;}
 function summary(){return '<div class="spec-summary"><div class="spec-summary-top"><span class="eyebrow">'+esc(spec.context.domain)+' · '+esc(spec.id)+' / V'+spec.version+'</span><span class="small-note">'+esc(spec.review.status)+' · author-defined</span></div><h2>'+esc(spec.context.task)+'</h2><p class="spec-source"><strong>Source</strong> '+esc(spec.context.source)+'</p>'+spec.criteria.map(cr=>'<article class="spec-criterion"><span class="dimension-chip">'+cr.dimension+'</span><div><h3>'+esc(cr.definition)+'</h3><p><strong>Evidence</strong> '+esc(cr.evidence)+'</p><dl class="anchor-list">'+['1','2','3'].map(n=>'<div><dt>'+n+'</dt><dd>'+esc(cr.anchors[n])+'</dd></div>').join('')+'</dl><p class="small-note">Turns '+cr.applicability.from_turn+'–'+(cr.applicability.to_turn??'end')+' · '+esc(cr.evaluator.type)+(cr.evaluator.type==='required_phrase'?' · exact text: “'+esc(cr.evaluator.phrase)+'”':'')+'</p></div></article>').join('')+'</div>';}
 function design(){
 const titles=['Set the context.','Define the behavior.','Make judgment explicit.','Review your specification.'];let body='';
 if(step===0)body=field('Domain','domain',spec.context.domain)+field('Task & expected behavior','task',spec.context.task,true)+field('Requirement or policy source','source',spec.context.source,true,'Quote a requirement or describe its source. This is an author-defined interpretation, not a compliance certification.')+field('People whose expectations matter','stakeholders',spec.context.stakeholders,false);
 if(step===1)body='<label class="design-field"><span>RHCA dimension</span><select name="dimension">'+Object.entries(names).map(([id,n])=>'<option value="'+id+'" '+(c().dimension===id?'selected':'')+'>'+id+' · '+n+'</option>').join('')+'</select><small>Choose a relevant dimension. You do not have to assess all four.</small></label>'+field('Observable behavioral criterion','definition',c().definition,true,'Describe what an evaluator can check, rather than “be trustworthy” or “be good”.');
 if(step===2){const e=c().evaluator;body=field('Observable evidence','evidence',c().evidence,true)+['1','2','3'].map(n=>field('Score '+n+' · '+({'1':'does not meet','2':'partly meets','3':'meets'}[n]),'anchor'+n,c().anchors[n],true)).join('')+'<div class="field-pair"><label class="design-field"><span>From turn</span><input name="from_turn" type="number" min="1" value="'+c().applicability.from_turn+'" required></label><label class="design-field"><span>Through turn · optional</span><input name="to_turn" type="number" min="1" value="'+(c().applicability.to_turn??'')+'" placeholder="End of conversation"></label></div><label class="design-field"><span>Evaluator binding</span><select name="evaluator" id="evaluator-binding">'+[['required_phrase','Exact required text · executable'],['python','Python evaluator · local harness'],['unbound','Not bound · draft only']].map(([v,n])=>'<option value="'+v+'" '+(e.type===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+(e.type==='required_phrase'?field('Text required in each applicable reply','phrase',e.phrase)+'<label class="check-field"><input type="checkbox" name="case_sensitive" '+(e.case_sensitive?'checked':'')+'> Case sensitive</label><p class="small-note">This narrow check emits 1 or 3. It does not establish semantic correctness or assess overall context alignment.</p>':e.type==='python'?field('Evaluator callable','callable',e.callable||'my_evaluator:judge')+field('Evaluator version','evaluator_version',e.version||'v1')+'<p class="small-note">Runs in your local Python environment; evidence references are validated.</p>':'<p class="small-note">You can save this design. Bind an evaluator before execution.</p>');}
 if(step===3)body=summary()+'<label class="check-field"><input type="checkbox" name="reviewed" '+(spec.review.status==='reviewed'?'checked':'')+'> I reviewed this specification for its intended context.</label><label class="design-field"><span>Review note · optional</span><textarea name="review_note" rows="2">'+esc(spec.review.note)+'</textarea><small>A local review record; no identity verification or organizational approval is implied.</small></label>';
 main().innerHTML=tabs('design')+'<section class="workspace-heading"><div><span class="eyebrow">EVALUATION DESIGN</span><h1>Expectations, made executable.</h1><p>Define the behavior before judging the answer.</p></div><button class="quiet-button" data-studio="import-spec">Import specification ↗</button></section><div class="design-layout"><aside class="design-steps" aria-label="Specification steps">'+['Context','Criteria','Evidence & anchors','Review & package'].map((n,i)=>'<button data-studio-step="'+i+'" class="'+(i===step?'active':'')+'" '+(i===step?'aria-current="step"':'')+'><span>0'+(i+1)+'</span>'+n+'</button>').join('')+'<div class="criterion-switch"><span class="eyebrow">CRITERIA</span>'+spec.criteria.map((cr,i)=>'<button data-criterion="'+i+'" class="'+(i===criterionIndex?'active':'')+'">'+esc(cr.dimension)+' · '+esc(cr.id)+'</button>').join('')+'<button class="text-link" data-studio="add-criterion">+ Add criterion</button>'+(spec.criteria.length>1?'<button class="text-link" data-studio="remove-criterion">Remove selected criterion</button>':'')+'</div></aside><section class="design-sheet"><div class="sheet-heading"><span class="eyebrow">STEP '+(step+1)+' OF 4</span><span class="small-note">Local draft · v'+spec.version+'</span></div><h2>'+titles[step]+'</h2>'+(errors.length?'<div class="validation-errors" role="alert">'+errors.map(e=>'<p>'+esc(e)+'</p>').join('')+'</div>':'')+'<form id="design-form">'+body+'<div class="design-actions">'+(step?'<button type="button" class="quiet-button" data-studio="previous">← Back</button>':'<button type="button" class="quiet-button" data-studio="reset-spec">Use Atlas preset</button>')+'<div>'+(step===3?'<button type="button" class="button secondary" data-studio="export-spec">Download evaluation package ↓</button><button type="submit" class="button primary">Save & continue to Run →</button>':'<button type="submit" class="button primary">Continue →</button>')+'</div></div></form></section></div><input type="file" id="spec-file" accept="application/json,.json" hidden>';
 }
 function runPage(){const executable=validateSpecification(spec,{executable:true});if(spec.context.task!==defaultSpecification().context.task||spec.criteria.length!==1||spec.criteria[0].evaluator.type!=='required_phrase'||spec.criteria[0].evaluator.phrase!=='Atlas')executable.push('The browser fixture requires the original Atlas task and one exact-text criterion. Your edited specification can run in the local harness.');main().innerHTML=tabs('run')+'<section class="workspace-heading"><div><span class="eyebrow">EXECUTE THE SPECIFICATION</span><h1>One specification. Repeatable checks.</h1><p>Use the reference fixture here, or connect your application in the local harness.</p></div><a class="text-link" href="#docs">Install the harness ↗</a></section><div class="run-layout"><section class="run-sheet"><span class="eyebrow">BROWSER FIXTURE · NO MODEL CALL</span><h2>Check the execution path.</h2><label class="design-field"><span>Target</span><select id="fixture-target"><option value="retain">Reference fixture · retains Atlas</option><option value="drift">Regression fixture · omits Atlas at turns 2–3</option></select></label><div class="run-summary-row"><span>Test suite</span><strong>Project handover · 4 fixed turns</strong></div><div class="run-summary-row"><span>Specification</span><strong>'+esc(spec.id)+' · v'+spec.version+'</strong></div><p class="small-note">Synthetic responses exercise the runner and exact-text evaluator. They are not model performance data. Edited scenarios and Python evaluators run through the local package.</p>'+(executable.length?'<div class="validation-errors">'+executable.map(e=>'<p>'+esc(e)+'</p>').join('')+'</div>':'')+'<button class="button primary" data-studio="execute" '+(busy||executable.length?'disabled':'')+'>'+(busy?'Checking fixture…':'Run fixture →')+'</button><div id="run-progress" role="status"></div></section><aside class="local-harness"><span class="eyebrow">YOUR MODEL OR APPLICATION</span><h2>Run it in your project.</h2><p>Use a Python function or an HTTP endpoint. Generation and assessment stay separate.</p><pre>deeproject run suite.json \\\n  --spec evaluation.json \\\n  --target my_app:reply \\\n  --out results/candidate</pre><a class="button secondary" href="#docs">Get the installation package ↓</a><a class="text-link" href="#design">Review specification ↗</a></aside></div>';}
 function results(current){const recent=api.index.runs.filter(r=>r.id.startsWith('FIXTURE-')||r.id.startsWith('IMPORT-')||r.id.startsWith('RUN-'));const groups=api.index.scenarios.filter(s=>s.id!=='fixture'&&s.id!=='imported'&&s.id!=='local');if(!groups.some(s=>s.id===filter))filter=groups[0]?.id;const selected=api.index.scenarios.find(s=>s.id===filter);const rows=api.index.runs.filter(r=>r.scenario===filter);const row=r=>'<article class="result-row"><div><h3>'+esc(r.model_label)+'</h3><p>'+esc(r.id)+' · '+r.turn_count+' turns · '+esc(r.family==='fixture'?'Synthetic fixture':r.configured?String(r.issue_count??0)+' observed issue(s) · configured checks':r.human_count?'Human + LLM records':'Recorded assessments')+'</p></div><a class="button secondary" href="'+api.route('diagnostics',r.id,r.first_issue_turn||1,r.dimension||'A')+'">Inspect →</a><a class="text-link" href="'+api.route('garden',r.id,1,r.dimension||'A')+'">Garden ↗</a></article>';
 main().innerHTML=tabs('workbench')+'<section class="workspace-heading"><div><span class="eyebrow">EVIDENCE & REGRESSIONS</span><h1>Find the behavior that changed.</h1><p>Inspect configured checks, original messages and differences between runs.</p></div><div class="heading-actions"><button class="quiet-button" data-action="import">Import results ↗</button><a class="button secondary" href="#compare">Compare runs ⇄</a></div></section>'+(recent.length?'<section class="result-section"><div class="section-label"><h2>Your executions</h2><a class="text-link" href="#run">New run +</a></div>'+recent.slice().reverse().map(row).join('')+'</section>':'<div class="results-empty"><span class="eyebrow">START WITH YOUR SPECIFICATION</span><p>Run the Atlas fixture or import a result from the local harness.</p><a class="text-link" href="#design">Design an evaluation →</a></div>')+'<section class="result-section"><div class="section-label"><h2>Recorded examples</h2><span class="small-note">Imported assessments · A only</span></div><div class="case-tabs">'+groups.map(s=>'<button data-studio-filter="'+esc(s.id)+'" class="'+(filter===s.id?'active':'')+'">'+esc(s.name)+'</button>').join('')+'</div><p class="small-note section-description">'+esc(selected?.description)+'</p>'+rows.map(row).join('')+'</section>';}
 async function comparePage(){const runs=[];for(const e of api.index.runs){try{const r=await api.getRun(e.id);if(r.specification)runs.push(r);}catch{}}if(location.hash.split('?')[0]!=='#compare')return;const opts=runs.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.model_label)+' · '+esc(r.id)+'</option>').join('');main().innerHTML=tabs('workbench')+'<section class="workspace-heading"><div><span class="eyebrow">REGRESSION REVIEW</span><h1>Compare evidence, not just averages.</h1><p>Keep the specification and scenario fixed when comparing target changes.</p></div></section>'+(runs.length<2?'<div class="results-empty"><p>Run both Atlas fixtures, or import two compatible harness results.</p><a class="button primary" href="#run">Run a fixture →</a></div>':'<section class="compare-sheet"><div class="field-pair"><label class="design-field"><span>Baseline</span><select id="compare-a">'+opts+'</select></label><label class="design-field"><span>Candidate</span><select id="compare-b">'+opts+'</select></label></div><button class="button primary" data-studio="compare">Compare runs →</button><div id="comparison-output" aria-live="polite"></div></section>');if(runs.length>=2)document.querySelector('#compare-b').selectedIndex=runs.length-1;}
 async function compareNow(){const a=await api.getRun(document.querySelector('#compare-a').value),b=await api.getRun(document.querySelector('#compare-b').value),reasons=compatibility(a,b),out=document.querySelector('#comparison-output');if(a.id===b.id)reasons.push('Choose two different runs.');if(reasons.length){out.innerHTML='<div class="validation-errors">'+reasons.map(r=>'<p>'+esc(r)+'</p>').join('')+'</div>';return;}let changes=[];for(const cr of a.specification.criteria)for(let i=0;i<a.turns.length;i++){const x=a.turns[i].evaluations?.find(v=>v.criterion_id===cr.id)?.score??null,y=b.turns[i]?.evaluations?.find(v=>v.criterion_id===cr.id)?.score??null;if(x!==y)changes.push({criterion:cr.id,turn:i+1,baseline:x,candidate:y,change:x===null||y===null?'Unknown':y>x?'Improved checkpoint':'Regressed checkpoint'});}const payload={baseline:a.id,candidate:b.id,changes,note:'Single-run comparison; improvement is not sustained recovery.'};out.innerHTML='<h2>'+changes.length+' changed checkpoint'+(changes.length===1?'':'s')+'</h2><div class="comparison-rows">'+changes.map(ch=>'<a href="'+api.route('diagnostics',b.id,ch.turn,b.dimension)+'"><span>'+esc(ch.criterion)+' · Turn '+ch.turn+'</span><span>'+esc(ch.baseline??'unknown')+' → '+esc(ch.candidate??'unknown')+'</span><strong>'+ch.change+'</strong></a>').join('')+'</div><p class="small-note">'+payload.note+'</p><button class="text-link" id="download-comparison">Download comparison · JSON ↓</button>';document.querySelector('#download-comparison').onclick=()=>saveFile('deeproject-comparison.json',JSON.stringify(payload,null,2),'application/json');}
 document.addEventListener('submit',e=>{if(e.target.id!=='design-form')return;e.preventDefault();capture();errors=[];if(step<3){step++;design();window.scrollTo(0,0)}else if(commit()){api.toast('Specification saved. Original assessments retain their original rubric.');location.hash='#run';}});
 document.addEventListener('click',async e=>{const s=e.target.closest('[data-studio]')?.dataset.studio,st=e.target.closest('[data-studio-step]')?.dataset.studioStep,ci=e.target.closest('[data-criterion]')?.dataset.criterion,fil=e.target.closest('[data-studio-filter]')?.dataset.studioFilter;
 if(st!==undefined){capture();step=Number(st);errors=[];design();}if(ci!==undefined){capture();criterionIndex=Number(ci);step=1;design();}if(fil){filter=fil;results();}if(!s)return;
 if(s==='previous'){capture();step=Math.max(0,step-1);design();}
 if(s==='add-criterion'){capture();spec.criteria.push({id:'criterion-'+Date.now(),dimension:'A',definition:'',evidence:'',anchors:{'1':'','2':'','3':''},applicability:{from_turn:1,to_turn:null},evaluator:{type:'unbound'}});criterionIndex=spec.criteria.length-1;step=1;design();}
 if(s==='remove-criterion'&&spec.criteria.length>1){capture();spec.criteria.splice(criterionIndex,1);criterionIndex=Math.max(0,criterionIndex-1);persist();design();}
 if(s==='reset-spec'){spec=defaultSpecification();saved=canonical(spec);try{localStorage.setItem('deeproject-v4-committed',saved)}catch{}step=0;criterionIndex=0;errors=[];persist();design();}
 if(s==='import-spec')document.querySelector('#spec-file').click();
 if(s==='export-spec'&&commit()){saveFile('evaluation.json',JSON.stringify(spec,null,2),'application/json');api.toast('Evaluation specification exported; no run results included.');design();}
 if(s==='execute'&&!busy){busy=true;const variant=document.querySelector('#fixture-target').value;runPage();try{await new Promise(r=>setTimeout(r,180));const run=fixtureRun(spec,variant);api.addRun(run);api.toast('Fixture executed. No model was called.');location.hash=api.route('diagnostics',run.id,1,run.dimension);}catch(err){api.toast(err.message)}finally{busy=false;if(location.hash==='#run')runPage();}}
 if(s==='compare')await compareNow();
 });
 document.addEventListener('input',e=>{if(e.target.closest('#design-form'))capture()});
 document.addEventListener('change',async e=>{if(e.target.closest('#design-form'))capture();if(e.target.id==='evaluator-binding'){capture();design();}if(e.target.id==='spec-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('Choose a specification smaller than 1 MB.');importSpec(JSON.parse(await file.text()));}catch(err){api.toast(err.message)}}});
 function importSpec(value){const found=validateSpecification(value);if(found.length)throw Error(found.join(' '));spec=structuredClone(value);spec.review=spec.review||{status:'draft',note:''};saved=canonical(spec);try{localStorage.setItem('deeproject-v4-committed',saved)}catch{}criterionIndex=0;step=3;errors=[];persist();if(location.hash==='#design')design();else location.hash='#design';api.toast('Specification imported. Its version and evaluator bindings are preserved.');}
 return {tabs,design,run:runPage,results,compare:comparePage,importSpec};
}

export function renderDocs(root){root.innerHTML='<section class="workspace-heading"><div><span class="eyebrow">LOCAL DEVELOPER TOOLKIT · 0.2.0A13</span><h1>From a specification to a real run.</h1><p>Install locally. Keep your application credentials in your own environment.</p></div>'+(document.body.dataset.runtime==='local'?'<span class="small-note">Local package installed · 0.2.0a13</span>':'<a class="button primary" href="downloads/deeproject_rhca-0.2.0a13-py3-none-any.whl" download>Download Python package ↓</a>')+'</section><section class="docs-layout"><article class="docs-copy"><h2>1. Install & create an example</h2><pre>python -m pip install ./deeproject_rhca-0.2.0a13-py3-none-any.whl\ndeeproject init my-evaluation\ncd my-evaluation</pre><p>Requires Python 3.10+. The example target is a synthetic fixture. Replace it with your application to test real behavior.</p><h2>2. Review your specification</h2><p>Use Design to define criteria, observable evidence and all three rating anchors. Download evaluation.json, then validate it locally.</p><pre>deeproject validate spec.json --executable</pre><h2>3. Run and inspect</h2><pre>deeproject run suite.json --spec spec.json \\\n  --target example_target:reply --fixture --out results/baseline\ndeeproject view results/baseline</pre><h2>4. Connect your application</h2><pre># my_app.py\ndef reply(messages):\n    # Call your model or application using the full history.\n    return your_application(messages)</pre><pre>deeproject run suite.json --spec evaluation.json \\\n  --target my_app:reply --target-id my-app/v2 \\\n  --out results/candidate</pre><p>A target returns assistant text. For HTTP, use <code>--target https://your-endpoint</code>; it receives <code>{"messages": [...]}</code> and returns <code>{"assistant": "..."}</code>. Optional authentication uses DEEPROJECT_TARGET_TOKEN. These are generic adapters, not built-in provider integrations.</p><h2>5. Compare changes</h2><pre>deeproject compare results/baseline results/candidate \\\n  --out comparison.json</pre><p>Use the same specification and input script. A changed checkpoint does not establish stable recovery.</p><h2>Custom evaluators</h2><p>Bind type <code>python</code> and callable <code>my_evaluator:judge</code>. The function receives prior turns and the criterion, returning score, explanation and evidence. It may call your chosen LLM judge; this package does not include a calibrated semantic judge.</p><pre>def judge(turns, criterion):\n    return {\n        "score": 3,\n        "explanation": "Explain against the anchors.",\n        "evidence": [{"turn": 1, "role": "assistant",\n                      "quote": "an exact quote from turn 1"}]\n    }</pre><p>Invalid or future-turn evidence becomes an evaluation error. Imported human and LLM records remain separate.</p></article><aside class="docs-aside"><h3>What is executable today</h3><p>Versioned specifications, fixed multi-turn scripts, Python and HTTP targets, exact-text checks, custom Python evaluators, evidence validation, reports and comparison.</p><h3>What the fixture proves</h3><p>The configured runner and evaluator execute. Synthetic responses do not establish model performance, semantic accuracy or safety.</p><h3>Open existing results</h3><p>Use Results → Import results for a local result.json. Use Design → Import specification for an evaluation package.</p><a class="text-link" href="#design">Open Evaluation Design →</a></aside></section>';}
